#include <bits/stdc++.h>
#define ll long long
#define int long long
using namespace std;
int ans1(int x,int y,int n, vector<int> &pref)
{
    return 2*pref[x-2*y]+pref[x]+3*pref[3*n-2*x+3*y];
    
}
void solve(){
    int n;
    cin>>n;
    vector<int> a(3*n);
    for(int i = 0; i < 3*n; i++) cin >> a[i];
    a.push_back(0);
    sort(a.begin(),a.end());
    reverse(a.begin()+1,a.end());
    vector<int> pref(3*n+1);
    for(int i=1;i<=3*n;i++)
    {
        pref[i]=pref[i-1]+a[i];
    }
    int ans=0;
    int yo=0,ye=0,y=0;
    for(int x=0;x<=2*n;x++)
    {
        if(x&1)
        {
            y=yo+2;
        }
        else
        {
            y=ye+2;
            
        }
        if(2*y>x)
         y--;
        if(2*y>x)
         y--;
        int ans0=ans1(x,y,n,pref);
        while(y>max(0ll,x-n))
        {
            if(ans1(x,y-1,n,pref)>ans0)
            {
                y=y-1;
                ans0=ans1(x,y,n,pref);
            }
            else
            break;
        }
        ans=max(ans,ans0);
        if(x&1)
        {
            yo=y;
        }
        else
        {
        ye=y;
            
        }

    }
    cout<<ans<<endl;
    
    
    
}
signed main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
	int t;
	cin>>t;
	while(t--){
	    solve();
	}
return 0;
}
